        required this.polygonNormalized,
        required this.rawText,
    });

    factory Word.fromRawJson(String str) => Word.fromJson(json.decode(str));

    String toRawJson() => json.encode(toJson());

    factory Word.fromJson(Map<String, dynamic> json) => Word(
        confidence: json["confidence"]?.toDouble(),
        polygonNormalized: List<List<double>>.from(json["polygon_normalized"].map((x) => List<double>.from(x.map((x) => x?.toDouble())))),
        rawText: json["raw_text"],
    );

    Map<String, dynamic> toJson() => {
        "confidence": confidence,
        "polygon_normalized": List<dynamic>.from(polygonNormalized.map((x) => List<dynamic>.from(x.map((x) => x)))),
        "raw_text": rawText,
    };
}

class Transform {
    final double? offsetX;
    final double? offsetY;
    final double? rotationDeg;
    final double? scaleX;
    final double? scaleY;

    Transform({
        this.offsetX,
        this.offsetY,
        this.rotationDeg,
        this.scaleX,
        this.scaleY,
    });

    factory Transform.fromRawJson(String str) => Transform.fromJson(json.decode(str));

    String toRawJson() => json.encode(toJson());

    factory Transform.fromJson(Map<String, dynamic> json) => Transform(
        offsetX: json["offset_x"]?.toDouble(),
        offsetY: json["offset_y"]?.toDouble(),
        rotationDeg: json["rotation_deg"]?.toDouble(),
        scaleX: json["scale_x"]?.toDouble(),
        scaleY: json["scale_y"]?.toDouble(),
    );

    Map<String, dynamic> toJson() => {
        "offset_x": offsetX,
        "offset_y": offsetY,
        "rotation_deg": rotationDeg,
        "scale_x": scaleX,
        "scale_y": scaleY,
    };
}

class EnumValues<T> {
    Map<String, T> map;
    late Map<T, String> reverseMap;

    EnumValues(this.map);

    Map<T, String> get reverse {
            reverseMap = map.map((k, v) => MapEntry(v, k));
            return reverseMap;
    }
}
